import{_ as a}from"./chunks/mlc-select.DbtJzQlb.js";import{_ as s,c as t,o as n,ag as o}from"./chunks/framework.Bzez9NG9.js";const r="/space/img/compare-mlc.png",i="/space/img/new-release.png",l="/space/img/asset.png",d="/space/img/mlc_compareee.png",p="/space/img/deploy_selected.png",c="/space/img/release-history.png",m="/space/img/history-mlc.png",P=JSON.parse('{"title":"Releases and deployments","description":"Compare IBM Planning Analytics and TM1 environments, organize model changes into releases, review differences, deploy assets across environments or Git, and maintain deployment history.","frontmatter":{"title":"Releases and deployments","description":"Compare IBM Planning Analytics and TM1 environments, organize model changes into releases, review differences, deploy assets across environments or Git, and maintain deployment history.","keywords":["IBM Planning Analytics","Planning Analytics","TM1","releases","deployments","model lifecycle","environment comparison","compare models","promotion","deployment","diff","Git"],"outline":"deep"},"headers":[],"relativePath":"doc/planning-analytics/releases-and-deployments.md","filePath":"doc/planning-analytics/releases-and-deployments.md"}'),h={name:"doc/planning-analytics/releases-and-deployments.md"};function g(y,e,u,f,v,w){return n(),t("div",null,e[0]||(e[0]=[o('<h1 id="releases-and-deployments" tabindex="-1">Releases and deployments <a class="header-anchor" href="#releases-and-deployments" aria-label="Permalink to &quot;Releases and deployments&quot;">​</a></h1><p>SPACE <strong>Model lifecycle</strong> provides a structured way to compare IBM Planning Analytics environments, organize related model changes into releases, review differences, and deploy assets to another Planning Analytics environment or Git.</p><p>A release is a curated collection of TM1 assets—such as processes, chores, cubes, and data—that can be refreshed, compared, reviewed, and deployed together. This helps teams move changes between development, test, and production environments while keeping the related assets and deployment activity organized in one place.</p><h2 id="compare-planning-analytics-environments" tabindex="-1">Compare Planning Analytics environments <a class="header-anchor" href="#compare-planning-analytics-environments" aria-label="Permalink to &quot;Compare Planning Analytics environments&quot;">​</a></h2><p>Use <strong>Compare models</strong> when you want to understand differences between two Planning Analytics environments before creating or deploying a release.</p><p><img src="'+a+'" alt="Compare models list" data-zoomable=""></p><ol><li>Select the <strong>Source environment</strong> and <strong>Target environment</strong>.</li><li>Choose the asset type to compare, such as processes, chores, or cubes.</li><li>Review the identified differences. Object names shown in red indicate mismatches.</li><li>Use the comparison options to show differences only, include system objects, or exclude data source passwords.</li></ol><p><img src="'+r+'" alt="Compare deploy options" data-zoomable=""></p><p>When you identify a change that needs to be moved, you can deploy directly from the comparison or add the relevant assets to a release for a more structured deployment workflow.</p><h2 id="create-a-release" tabindex="-1">Create a release <a class="header-anchor" href="#create-a-release" aria-label="Permalink to &quot;Create a release&quot;">​</a></h2><p>Open <strong>Model lifecycle</strong> to view existing releases together with their descriptions and last updated times.</p><p>Select <strong>New release</strong> to create a release for a related set of changes.</p><p><img src="'+i+'" alt="New release modal" data-zoomable=""></p><p>Enter a name and, optionally, a description. A clear release name and description make it easier to understand the purpose of the change when reviewing the release later.</p><h2 id="manage-release-assets" tabindex="-1">Manage release assets <a class="header-anchor" href="#manage-release-assets" aria-label="Permalink to &quot;Manage release assets&quot;">​</a></h2><p>Open a release to see its saved assets, source environments, and last refresh times.</p><p><img src="'+l+'" alt="Release asset list" data-zoomable=""></p><p>Available actions include:</p><ul><li><strong>Compare</strong> — compare a saved asset with the corresponding object in the current target environment.</li><li><strong>Deploy</strong> — deploy selected assets to IBM Planning Analytics or Git.</li><li><strong>Sync latest</strong> — refresh saved assets from their source environment.</li><li><strong>Delete</strong> — remove assets from the release.</li></ul><p>Select an asset to open the diff viewer and inspect changes at the code or definition level.</p><p><img src="'+d+'" alt="Asset compare view" data-zoomable=""></p><p>Use <strong>Previous difference</strong> and <strong>Next difference</strong> to move through the identified changes before deployment.</p><h2 id="deploy-changes" tabindex="-1">Deploy changes <a class="header-anchor" href="#deploy-changes" aria-label="Permalink to &quot;Deploy changes&quot;">​</a></h2><p>Select the assets you want to deploy and choose <strong>Deploy</strong>.</p><p><img src="'+p+'" alt="Deploy dialog" data-zoomable=""></p><p>Choose the destination—an IBM Planning Analytics environment or configured Git repository—and confirm the deployment.</p><p>For smaller changes identified during an environment comparison, SPACE also supports deploying directly from <strong>Compare models</strong> without first assembling a release.</p><p>For coordinated changes involving multiple related assets, a release provides a structured way to keep those assets together and review them before deployment.</p><h2 id="keep-release-assets-current" tabindex="-1">Keep release assets current <a class="header-anchor" href="#keep-release-assets-current" aria-label="Permalink to &quot;Keep release assets current&quot;">​</a></h2><p>A release retains the assets that were added to it. When the corresponding objects continue to change in the source environment, use <strong>Sync latest</strong> to refresh the release with their current versions.</p><p>You can then compare the refreshed assets with the target environment before deployment.</p><p>This is useful when a release is assembled over time while development continues.</p><h2 id="review-release-history" tabindex="-1">Review release history <a class="header-anchor" href="#review-release-history" aria-label="Permalink to &quot;Review release history&quot;">​</a></h2><p>SPACE records release activity so you can review how the release has changed over time.</p><p><img src="'+c+'" alt="Release history view" data-zoomable=""></p><p>Select the timestamp in the upper-right corner of the release to view its history, including the user, time, and description associated with recorded add, compare, refresh, and deployment activity.</p><p><img src="'+m+'" alt="History list" data-zoomable=""></p><p>The release history provides a useful record for reviewing deployment activity and understanding how a release progressed from preparation through deployment.</p>',38)]))}const A=s(h,[["render",g]]);export{P as __pageData,A as default};
